create or replace function public.remove_friend(p_target uuid) returns void language plpgsql security definer set search_path='' as $$begin delete from public.friend_requests where status='accepted' and((sender_id=(select auth.uid())and receiver_id=p_target)or(sender_id=p_target and receiver_id=(select auth.uid())));end;$$;create or replace function public.get_social_feed(p_limit integer default 50,p_before timestamptz default null) returns setof public.social_activity language sql stable security definer set search_path='' as $$select a from public.social_activity a where a.created_at<coalesce(p_before,'infinity'::timestamptz)and not exists(select 1 from public.social_blocks b where(b.blocker_id=(select auth.uid())and b.blocked_id=a.user_id)or(b.blocker_id=a.user_id and b.blocked_id=(select auth.uid())))and(a.user_id=(select auth.uid())or a.visibility='public'or(a.visibility='friends'and exists(select 1 from public.friend_requests f where f.status='accepted'and((f.sender_id=(select auth.uid())and f.receiver_id=a.user_id)or(f.receiver_id=(select auth.uid())and f.sender_id=a.user_id)))))order by a.created_at desc limit greatest(1,least(p_limit,100));$$;revoke all on function public.remove_friend(uuid),public.get_social_feed(integer,timestamptz) from public,anon;grant execute on function public.remove_friend(uuid),public.get_social_feed(integer,timestamptz) to authenticated;